// Generated by AI (UnitTest MCP)
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { readAdrFiles } from "../../../scripts/adr-files.mjs";

const directories = [];
const adrDir = () => {
  const dir = mkdtempSync(join(tmpdir(), "adr-files-"));
  directories.push(dir);
  return dir;
};

afterEach(() => {
  for (const dir of directories.splice(0)) rmSync(dir, { recursive: true, force: true });
});

const write = (dir, name, body) => writeFileSync(join(dir, name), body);

describe("readAdrFiles", () => {
  it("reads number, title and status", () => {
    const dir = adrDir();
    write(
      dir,
      "0039-every-waiver-ends.md",
      "# ADR-0039: Every waiver ends\n\n- Status: Accepted\n"
    );

    expect(readAdrFiles(dir)).toEqual([
      {
        number: "0039",
        file: "0039-every-waiver-ends.md",
        path: `${dir.split("\\").join("/")}/0039-every-waiver-ends.md`,
        title: "Every waiver ends",
        status: "Accepted",
      },
    ]);
  });

  // The bug this exists for: ADR-0032 wraps its supersession reference onto the
  // next line. The status regex stopped at the newline, so the file read as a
  // bare "Superseded by" — and that was reported, and repeated to a human, as a
  // decision nobody could attribute. The answer was one line further down.
  it("reads a status whose reference wraps onto the next line", () => {
    const dir = adrDir();
    write(
      dir,
      "0032-single-checkout.md",
      "# ADR-0032: Single checkout\n\n" +
        "- Status: Superseded by\n" +
        "   [ADR-0038](0038-isolated-worktrees.md)\n" +
        "- Date: 2026-07-27\n"
    );

    expect(readAdrFiles(dir)[0].status).toBe(
      "Superseded by [ADR-0038](0038-isolated-worktrees.md)"
    );
  });

  it("does not swallow the following bullet into the status", () => {
    const dir = adrDir();
    write(
      dir,
      "0040-thing.md",
      "# ADR-0040: Thing\n\n- Status: Accepted\n- Date: 2026-07-27\n- Deciders: someone\n"
    );

    expect(readAdrFiles(dir)[0].status).toBe("Accepted");
  });

  it("rejects a status it does not recognise rather than guessing", () => {
    const dir = adrDir();
    write(dir, "0041-thing.md", "# ADR-0041: Thing\n\n- Status: Probably fine\n");

    expect(() => readAdrFiles(dir)).toThrow(/unrecognised status/);
  });

  it("orders by number and ignores non-ADR files", () => {
    const dir = adrDir();
    write(dir, "0002-b.md", "# ADR-0002: B\n\n- Status: Accepted\n");
    write(dir, "0001-a.md", "# ADR-0001: A\n\n- Status: Proposed\n");
    write(dir, "README.md", "# Index\n");

    expect(readAdrFiles(dir).map((a) => a.number)).toEqual(["0001", "0002"]);
  });
});
